    "prem.f6":         { en:"Share Games", es:"Compartir partidas", fr:"Partager des parties", pt:"Compartilhar partidas", ar:"مشاركة المباريات", zh:"分享比赛", nl:"Spellen delen", de:"Spiele teilen", hi:"गेम शेयर करें", bn:"খেলা শেয়ার করুন", id:"Bagikan permainan", ur:"گیمز شیئر کریں", tr:"Oyunları paylaş", it:"Condividere partite", ja:"ゲームを共有", ko:"게임 공유", ru:"Делиться играми" },
